const input =
  $input.first()?.json ?? {};

const rawLockValue =
  input.lock_acquired;

const lockAcquired =
  rawLockValue === true
  || rawLockValue === 1
  || String(
    rawLockValue ?? ''
  )
    .trim()
    .toLowerCase() === 'true'
  || String(
    rawLockValue ?? ''
  )
    .trim() === '1';

return [
  {
    json: {
      ...input,

      lock_acquired_raw:
        rawLockValue ?? null,

      lock_acquired_boolean:
        lockAcquired,

      lock_acquired_flag:
        lockAcquired
          ? 1
          : 0,

      lock_route:
        lockAcquired
          ? 'LOCK_ACQUIRED'
          : 'LOCK_NOT_ACQUIRED',

      workflow_code:
        'WF-018',

      normalized_at:
        new Date().toISOString(),
    },
  },
];

const items =
  $input.all();

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

return items.map((item) => {
  const input =
    item.json ?? {};

  const rawHasEvaluation =
    input.has_evaluation;

  const rawBoolean =
    rawHasEvaluation === true
    || rawHasEvaluation === 1
    || String(
      rawHasEvaluation ?? ''
    )
      .trim()
      .toLowerCase() === 'true'
    || String(
      rawHasEvaluation ?? ''
    )
      .trim() === '1';

  const evaluationId =
    String(
      input.evaluation_id ?? ''
    ).trim();

  const hasValidEvaluationId =
    uuidPattern.test(
      evaluationId
    );

  const hasEvaluation =
    rawBoolean
    && hasValidEvaluationId;

  return {
    json: {
      ...input,

      has_evaluation_raw:
        rawHasEvaluation ?? null,

      has_evaluation_boolean:
        hasEvaluation,

      has_evaluation_flag:
        hasEvaluation
          ? 1
          : 0,

      has_valid_evaluation_id:
        hasValidEvaluationId,

      normalized_evaluation_id:
        hasValidEvaluationId
          ? evaluationId
          : null,

      evaluation_route:
        hasEvaluation
          ? 'EVALUATION_AVAILABLE'
          : 'NO_EVALUATIONS',

      workflow_code:
        'WF-018',

      normalized_at:
        new Date().toISOString(),
    },
  };
});

const items = $input.all();

const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

return items.map((item) => {
  const input =
    item.json ?? {};

  const rawHasPlan =
    input.has_plan;

  const rawBoolean =
    rawHasPlan === true
    || rawHasPlan === 1
    || String(
      rawHasPlan ?? ''
    )
      .trim()
      .toLowerCase() === 'true'
    || String(
      rawHasPlan ?? ''
    )
      .trim() === '1';

  const planId =
    String(
      input.action_plan_id ?? ''
    ).trim();

  const validPlanId =
    uuidPattern.test(
      planId
    );

  const hasPlan =
    rawBoolean
    && validPlanId;

  return {
    json: {
      ...input,

      has_plan_boolean:
        hasPlan,

      has_plan_flag:
        hasPlan ? 1 : 0,

      has_valid_plan_id:
        validPlanId,

      normalized_action_plan_id:
        validPlanId
          ? planId
          : null,

      plan_route:
        hasPlan
          ? 'PLAN_GENERATED'
          : 'PLAN_NOT_GENERATED',

      workflow_code:
        'WF-018',

      normalized_at:
        new Date().toISOString(),
    },
  };
});
